ALTER TABLE "spideryarn"."citation_investigations" DROP CONSTRAINT "citation_investigations_counts";--> statement-breakpoint
ALTER TABLE "spideryarn"."citation_investigations" ADD CONSTRAINT "citation_investigations_counts" CHECK ("spideryarn"."citation_investigations"."extracts_read" >= 0 and ("spideryarn"."citation_investigations"."extracts_read" >= 1 or coalesce("spideryarn"."citation_investigations"."paper_state" = 'read', false)) and "spideryarn"."citation_investigations"."longest_extract_words" >= 0 and ("spideryarn"."citation_investigations"."searches" is null or "spideryarn"."citation_investigations"."searches" >= 0));